<?php startform('ai',['item_id'=>$itemid,'order_id'=>$orderid],true); ?><label>Task<?php selectbox('task',['instructions'=>'Read and follow sheet instructions','write'=>'Write clear requirements','organize'=>'Organize details','extract'=>'Extract from PDF, image or text','followup'=>'Draft buyer follow-up','next'=>'Suggest next actions','steps'=>'Suggest production steps'],$_POST['task']??$_GET['task']??'organize'); ?></label><?php area('Instructions / pasted buyer text (optional when using a file)','input',$_POST['input']??'',6); ?>
