<?php if($orderid): ?><label>Or select a saved order / product sheet<select name="file_id"><option value="">No saved file selected</option><?php foreach(rows('SELECT id,original_name FROM order_files WHERE order_id=? ORDER BY id DESC',[$orderid]) as $file): ?><option value="<?=$file['id']?>" <?=($_POST['file_id']??$_GET['file_id']??0)==$file['id']?'selected':''?>><?=e($file['original_name'])?></option><?php endforeach ?></select></label><?php endif ?><button <?=$enabled?'':'disabled'?>>Generate draft</button><button id="ai-cancel" type="button" class="secondary" hidden>Cancel wait</button><div id="ai-status" role="status" aria-live="polite" hidden></div></form><p class="muted">Choose either one new upload or one saved sheet. Direct assistant uploads are used for this request only; upload through the order form to keep a copy. PDF/image extraction requires a vision-capable model. Review unclear measurements and quantities. Follow-ups are drafts and are never sent automatically.</p></section>
<section class="card"><h2>Draft for review</h2><?php if($draft): ?><textarea id="ai-result" rows="16"><?=e($draft['text'])?></textarea><button class="secondary" type="button" data-copy="ai-result">Copy draft</button><p id="copy-status" class="muted" role="status"></p>
